def restore(value):
    result=deepcopy(value)
    for op in reversed(value[KEY]['inverse_operations']):
        parent,key=parent_at(result,op['path'])
        if op['existed']:parent[key]=deepcopy(op['before'])
        else:parent.pop(key)
    return result

